#include <efi.h>
#include <efilib.h>
#include <efipciio.h>
#define DELAY 30
#define MAX_EXT 32
static EFI_GUID PciGuid=EFI_PCI_IO_PROTOCOL_GUID;
static EFI_STATUS c32(EFI_PCI_IO*p,UINT32 o,UINT32*v){return uefi_call_wrapper(p->Pci.Read,5,p,EfiPciIoWidthUint32,o,1,v);}
static EFI_STATUS m32(EFI_PCI_IO*p,UINT64 o,UINT32*v){return uefi_call_wrapper(p->Mem.Read,6,p,EfiPciIoWidthUint32,0,o,1,v);}
static void wait_exit(void){Print(u"\r\nREAD-ONLY / NO DMA / NO WRITES\r\nEXIT %u SEC...\r\n",DELAY);uefi_call_wrapper(BS->Stall,1,(UINTN)DELAY*1000000);}
static EFI_STATUS find(EFI_HANDLE image,EFI_PCI_IO**out,UINTN*os,UINTN*ob,UINTN*od,UINTN*of){EFI_HANDLE*hs;UINTN n=0,i;EFI_STATUS s=LibLocateHandle(ByProtocol,&PciGuid,NULL,&n,&hs);if(EFI_ERROR(s))return s;for(i=0;i<n;i++){EFI_PCI_IO*p;UINTN sg,b,d,f;UINT32 cl;if(EFI_ERROR(uefi_call_wrapper(BS->OpenProtocol,6,hs[i],&PciGuid,(void**)&p,image,NULL,EFI_OPEN_PROTOCOL_GET_PROTOCOL)))continue;if(EFI_ERROR(uefi_call_wrapper(p->GetLocation,5,p,&sg,&b,&d,&f)))continue;if(EFI_ERROR(c32(p,8,&cl)))continue;if(((cl>>24)&255)==0x0c&&((cl>>16)&255)==3&&((cl>>8)&255)==0x30){*out=p;*os=sg;*ob=b;*od=d;*of=f;return EFI_SUCCESS;}}return EFI_NOT_FOUND;}
static void ext(EFI_PCI_IO*p,UINT32 base,UINT32*legacy,UINT32*prot,UINT32*dbg){UINT32 off=base,n=0,h,d1,d2;*legacy=*prot=*dbg=0;while(off&&n++<MAX_EXT){if(EFI_ERROR(m32(p,off,&h)))break;UINT8 id=h&255,next=(h>>8)&255;Print(u" %04x:%02x",off,id);if(id==1){*legacy=off;if(!EFI_ERROR(m32(p,off+4,&d1)))Print(u" B%u/O%u",(d1>>16)&1,(d1>>24)&1);}else if(id==2){*prot=off;if(!EFI_ERROR(m32(p,off+4,&d1))&&!EFI_ERROR(m32(p,off+8,&d2))){UINT8 po=d2&255,pc=(d2>>8)&255,psic=(d2>>28)&15,maj=(d1>>24)&255,min=(d1>>16)&255;Print(u" v%02x.%02x P%u+%u PSI%u",maj,min,po,pc,psic);}}else if(id==10)*dbg=off;if(!next)break;off+=(UINT32)next*4;}}
EFI_STATUS efi_main(EFI_HANDLE image,EFI_SYSTEM_TABLE*st){EFI_PCI_IO*p=NULL;UINTN sg,b,d,f;UINT32 id,cl,b0,b1,cap,h1,h2,h3,hcc1,hcc2,db,rt,op,cmd,sts,cfg,extp;EFI_STATUS s;InitializeLib(image,st);Print(u"xHCI CAP/DMA PROBE (READ ONLY)\r\n");s=find(image,&p,&sg,&b,&d,&f);if(EFI_ERROR(s)){Print(u"xHCI NOT FOUND %r\r\n",s);wait_exit();return s;}c32(p,0,&id);c32(p,8,&cl);c32(p,0x10,&b0);c32(p,0x14,&b1);UINT64 bar=((UINT64)b1<<32)|(b0&~15U);Print(u"PCI %04x:%02x:%02x.%x %04x:%04x BAR=%016lx\r\n",sg,b,d,f,id&65535,id>>16,bar);if(EFI_ERROR(m32(p,0,&cap))||EFI_ERROR(m32(p,4,&h1))||EFI_ERROR(m32(p,8,&h2))||EFI_ERROR(m32(p,0xc,&h3))||EFI_ERROR(m32(p,0x10,&hcc1))||EFI_ERROR(m32(p,0x14,&db))||EFI_ERROR(m32(p,0x18,&rt))||EFI_ERROR(m32(p,0x1c,&hcc2))){Print(u"CAP READ FAIL\r\n");wait_exit();return EFI_DEVICE_ERROR;}op=cap&255;UINT32 ver=(cap>>16)&65535,ports=(h1>>24)&255,slots=h1&255,intr=(h1>>8)&2047,scratch=((h2>>27)&31)<<5|((h2>>21)&31),csz=(hcc1>>2)&1,ac64=hcc1&1;extp=((hcc1>>16)&65535)<<2;Print(u"VER=%04x CAP=%02x SLOTS=%u INTR=%u PORTS=%u\r\n",ver,op,slots,intr,ports);Print(u"AC64=%u CSZ=%u SCRATCH=%u DB=%x RT=%x\r\n",ac64,csz,scratch,db,rt);Print(u"HCC1=%08x HCC2=%08x HCS2=%08x\r\n",hcc1,hcc2,h2);if(!EFI_ERROR(m32(p,op,&cmd))&&!EFI_ERROR(m32(p,op+4,&sts))&&!EFI_ERROR(m32(p,op+0x38,&cfg)))Print(u"RUN=%u HCH=%u HSE=%u CNR=%u HCE=%u CFG=%x\r\n",cmd&1,sts&1,(sts>>2)&1,(sts>>11)&1,(sts>>12)&1,cfg);Print(u"EXT:");UINT32 leg,pr,dbg;ext(p,extp,&leg,&pr,&dbg);Print(u"\r\nLEG=%x PROTO=%x DBG=%x\r\n",leg,pr,dbg);wait_exit();return EFI_SUCCESS;}
